escenas.animacion:
const W=A.W, ac=A.accent;
A.bg('#0b1630','#050a18',true);
const kTren=A.k('trenes',0.33), kMet=A.k('Metro',1.0), kFi=A.k('fierro…',3.0), kRu2=A.k('ruedan',3.33,2), kNeu=A.k('neumáticos,',4.0), kAuto=A.k('auto.',5.0);
const mv=A.p(kTren-0.1,1.5,'whip');
const ox=A.lerp(1250,0,mv);
const tireM=A.p(kNeu,0.45,'snapSettle');
const bob=Math.sin(t*9)*2*(1-A.clamp(mv))+Math.sin(t*2.2)*1.5;

function wheel(x,y,r,rot,m){
  ctx.save();ctx.translate(x,y);ctx.rotate(rot);
  if(m<1){ctx.globalAlpha=1-m;
    ctx.beginPath();ctx.arc(0,0,r*1.12,0,7);ctx.fillStyle='#5d6672';ctx.fill();
    ctx.beginPath();ctx.arc(0,0,r,0,7);ctx.fillStyle='#aab3be';ctx.fill();
    ctx.strokeStyle='#e6ebf0';ctx.lineWidth=r*0.06;ctx.stroke();
    for(let i=0;i<6;i++){const a=i*Math.PI/3;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(a)*r*0.8,Math.sin(a)*r*0.8);ctx.strokeStyle='#6c7580';ctx.lineWidth=r*0.1;ctx.stroke();}
    ctx.beginPath();ctx.arc(0,0,r*0.22,0,7);ctx.fillStyle='#e6ebf0';ctx.fill();}
  if(m>0){ctx.globalAlpha=m;const s=0.6+0.4*m;ctx.scale(s,s);
    ctx.beginPath();ctx.arc(0,0,r*1.15,0,7);ctx.fillStyle='#161616';ctx.fill();
    for(let i=0;i<16;i++){const a=i*Math.PI/8;ctx.save();ctx.rotate(a);ctx.fillStyle='#2e2e2e';ctx.fillRect(r*0.95,-r*0.07,r*0.2,r*0.14);ctx.restore();}
    ctx.beginPath();ctx.arc(0,0,r*0.62,0,7);ctx.fillStyle='#c9ced4';ctx.fill();
    ctx.beginPath();ctx.arc(0,0,r*0.62,0,7);ctx.strokeStyle=ac;ctx.lineWidth=r*0.07;ctx.stroke();
    for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ctx.beginPath();ctx.arc(Math.cos(a)*r*0.36,Math.sin(a)*r*0.36,r*0.08,0,7);ctx.fillStyle='#555';ctx.fill();}
    ctx.beginPath();ctx.arc(0,0,r*0.14,0,7);ctx.fillStyle='#333';ctx.fill();}
  ctx.restore();
}

// vía
const tyY=900;
A.line([[40,tyY],[1040,tyY]],{stroke:'#8a95a5',lw:8,progress:A.p(0,0.6,'glide')});
A.rect(40,tyY+4,1000,14,{fill:'#1c2740',alpha:A.p(0,0.6)});

// tren
A.with(()=>{
  const y0=560+bob;
  A.rect(100,y0,880,270,{r:40,fill:'#e9edf2',stroke:'#ffffff',lw:4});
  A.lib.hatch(ctx,[[100,y0+200],[980,y0+200],[980,y0+270],[100,y0+270]],{angle:-0.6,spacing:14,width:2,color:'rgba(20,30,60,0.25)'});
  A.rect(100,y0+165,880,26,{fill:ac});
  for(let i=0;i<4;i++)A.rect(150+i*200,y0+40,150,100,{r:14,fill:'#1d3b6a',stroke:'#0b1630',lw:4});
  A.rect(440,y0+30,0,0,{});
  A.rect(115,y0+30,26,130,{r:8,fill:'#0b1630'});
  A.circle(950,y0+215,12,{fill:ac,glow:20});
  // bogies
  A.rect(170,y0+255,300,30,{r:10,fill:'#2a3448'});A.rect(610,y0+255,300,30,{r:10,fill:'#2a3448'});
  const wr=46;
  [230,410,670,850].forEach((x,i)=>{
    const loc=A.clamp(tireM*1.3-i*0.08);
    wheel(x,tyY-wr*1.12+2,wr,ox/wr+ (t>kTren+1.5? 0:0),loc);
  });
},{x:ox,y:0});

// etiqueta Metro de Santiago
const lp=A.pop(kMet,0.45);
if(t>kMet)A.label('METRO DE SANTIAGO',540,480,{size:46,bg:ac,color:'#0b1630',scale:lp});

// lupa
const cx=360,cy=1545,cr=175;
const cp=A.p(kFi-0.35,0.5,'snapSettle');
if(cp>0){
  A.line([[410,945],[cx+40,cy-cr]],{stroke:'#ffffff',lw:4,dash:[12,10],alpha:0.7,progress:cp});
  A.with(()=>{
    ctx.save();ctx.beginPath();ctx.arc(cx,cy,cr,0,7);ctx.fillStyle='#0e1d3d';ctx.fill();ctx.clip();
    const ry=cy+95;
    // riel -> pista plana
    ctx.globalAlpha=1-tireM;
    ctx.fillStyle='#aab3be';ctx.fillRect(cx-200,ry,400,24);ctx.fillStyle='#6c7580';ctx.fillRect(cx-200,ry+24,400,50);
    ctx.globalAlpha=tireM;
    ctx.fillStyle='#7d8796';ctx.fillRect(cx-200,ry,400,90);
    ctx.globalAlpha=1;
    A.lib.hatch(ctx,[[cx-200,ry+10],[cx+200,ry+10],[cx+200,ry+90],[cx-200,ry+90]],{angle:0.7,spacing:12,width:2,color:'rgba(0,0,0,0.3)'});
    wheel(cx,ry-92,82,-t*2.5,tireM);
    ctx.restore();
    A.circle(cx,cy,cr,{stroke:ac,lw:8});
  },{x:cx,y:cy,scale:cp});
  // etiqueta
  if(t<kNeu){
    const fp=A.pop(kFi,0.4);
    if(t>kFi)A.label('FIERRO',cx,cy-cr-10,{size:44,bg:'#ffffff',color:'#0b1630',scale:fp});
    const xp=A.p(kRu2,0.35,'crashIn');
    if(xp>0){A.line([[cx-120,cy-120],[cx+120,cy+120]],{stroke:'#ff3b3b',lw:16,progress:xp});
      A.line([[cx+120,cy-120],[cx-120,cy+120]],{stroke:'#ff3b3b',lw:16,progress:A.p(kRu2+0.15,0.3,'crashIn')});}
  } else {
    A.rings(cx,cy-10,kNeu,{count:3,speed:500,gap:0.15,maxR:300,color:ac,lw:6});
    A.label('NEUMÁTICO',cx,cy-cr-10,{size:46,bg:ac,color:'#0b1630',scale:A.pop(kNeu,0.45)});
  }
}
// auto
const ap=A.p(kAuto-0.25,0.55,'whip');
if(ap>0){
  const axo=A.lerp(500,0,ap);
  A.with(()=>{
    const bx=690,by=1560;
    ctx.beginPath();ctx.moveTo(bx,by+40);ctx.lineTo(bx,by-10);ctx.quadraticCurveTo(bx+20,by-30,bx+70,by-35);
    ctx.lineTo(bx+110,by-90);ctx.lineTo(bx+220,by-90);ctx.lineTo(bx+270,by-35);ctx.quadraticCurveTo(bx+330,by-30,bx+340,by);ctx.lineTo(bx+340,by+40);ctx.closePath();
    ctx.fillStyle=ac;ctx.fill();ctx.strokeStyle='#ffffff';ctx.lineWidth=4;ctx.stroke();
    A.rect(bx+120,by-78,90,40,{r:6,fill:'#1d3b6a'});
    wheel(bx+75,by+45,34,axo/34,1);wheel(bx+265,by+45,34,axo/34,1);
    A.line([[bx-20,by+86],[bx+360,by+86]],{stroke:'#8a95a5',lw:5});
  },{x:axo,y:0});
  A.label('= AUTO',855,1395,{size:48,bg:'#ffffff',color:'#0b1630',scale:A.pop(kAuto,0.45)});
}
A.flash(kNeu,0.25,0.35);

const W=A.W;
A.bg('#0b1830','#050b18',true);
const k1=A.k('1,',1.333),k2=A.k('2',1.667),k5=A.k('5.',2.333),kT=A.k('tecnología',3.333),kF=A.k('francesa',3.667),kM=A.k('Metro',5.0),kP=A.k('París',5.667);
function res(pts,n){const L=[0];for(let i=1;i<pts.length;i++){L.push(L[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));}const T=L[L.length-1],out=[];for(let j=0;j<n;j++){const d=T*j/(n-1);let s=1;while(s<pts.length-1&&L[s]<d)s++;const f=(d-L[s-1])/Math.max(1e-6,L[s]-L[s-1]);out.push([A.lerp(pts[s-1][0],pts[s][0],f),A.lerp(pts[s-1][1],pts[s][1],f)]);}return out;}
function hx(c){const n=parseInt(c.slice(1),16);return[(n>>16)&255,(n>>8)&255,n&255];}
function mix(a,b,p){const x=hx(a),y=hx(b);return 'rgb('+x.map((v,i)=>Math.round(A.lerp(v,y[i],p))).join(',')+')';}
const N=30;
const m=A.p(kF-0.35,0.8,'whip');
const rr=A.p(kM-0.15,0.6,'snapSettle');
const cx=540,cy=770;
// faint other lines (context)
const ga=A.p(0,1.0,'softInOut')*(1-m)*0.35;
if(ga>0.01){
 A.line([[150,520],[400,600],[650,560],[930,760]],{stroke:'#8fa6c8',lw:8,alpha:ga,progress:A.p(0,1.1,'glide')});
 A.line([[300,440],[380,700],[420,900],[700,1080]],{stroke:'#8fa6c8',lw:8,alpha:ga,progress:A.p(0.2,1.1,'glide')});
 A.text('SANTIAGO',150,470,{size:36,color:'#9fb7da',weight:800,align:'left',alpha:A.p(0.1,0.5)*(1-m)});
}
const lines=[
 {k:k5,col:'#2ECC71',to:'#1f4fd1',x:340,pts:[[230,1060],[350,900],[480,760],[640,600],[760,520],[900,470]]},
 {k:k2,col:'#FFC93C',to:'#ffffff',x:540,pts:[[600,440],[580,620],[560,800],[540,950],[520,1100]]},
 {k:k1,col:'#FF3D3D',to:'#FF3D3D',x:740,pts:[[130,690],[330,700],[520,670],[700,640],[950,620]]}
];
const ctx2=ctx;
ctx2.save();
if(rr>0){ctx2.beginPath();ctx2.arc(cx,cy,A.lerp(430,240,rr),0,Math.PI*2);ctx2.clip();}
lines.forEach((L,li)=>{
 const dp=A.p(L.k-0.05,0.6,'glide');
 if(dp<=0)return;
 const src=res(L.pts,N);
 const pts=src.map((p,j)=>{const ty=A.lerp(560,980,j/(N-1));let x=A.lerp(p[0],L.x,m),y=A.lerp(p[1],ty,m);x+=Math.sin(y*0.02+t*4)*7*m*(1-rr);return[x,y];});
 const upto=dp*(N-1);
 ctx2.beginPath();
 for(let j=0;j<=Math.ceil(upto)&&j<N;j++){let p=pts[j];if(j>upto){const a=pts[j-1],f=upto-(j-1);p=[A.lerp(a[0],p[0],f),A.lerp(a[1],p[1],f)];}j?ctx2.lineTo(p[0],p[1]):ctx2.moveTo(p[0],p[1]);}
 ctx2.strokeStyle=mix(L.col,L.to,m);ctx2.lineWidth=A.lerp(20,202,m);ctx2.lineCap=m>0.5?'butt':'round';ctx2.lineJoin='round';
 ctx2.shadowColor=L.col;ctx2.shadowBlur=20*(1-m);ctx2.stroke();ctx2.shadowBlur=0;
 const fa=dp*(1-A.clamp(m*3));
 if(fa>0.01){
  for(let j=0;j<N;j+=7){if(j<=upto)A.circle(pts[j][0],pts[j][1],9,{fill:'#0b1830',stroke:'#fff',lw:4,alpha:fa});}
  const s=((t*0.16+li*0.33)%1)*upto;const j=Math.min(N-2,Math.floor(s));const a=pts[j],b=pts[j+1];const f=s-j;
  const ang=Math.atan2(b[1]-a[1],b[0]-a[0]);
  A.with(()=>{A.rect(-30,-12,60,24,{r:8,fill:'#fff',alpha:fa});A.circle(-16,13,6,{fill:'#222',alpha:fa});A.circle(16,13,6,{fill:'#222',alpha:fa});},{x:A.lerp(a[0],b[0],f),y:A.lerp(a[1],b[1],f),rot:ang});
 }
});
ctx2.restore();
if(m>0.02&&rr<1){A.flash(kF,0.25,0.25);}
if(rr>0){
 A.circle(cx,cy,A.lerp(430,240,rr),{stroke:'#ffffff',lw:14,alpha:rr});
 const ps=A.pop(kM,0.45);
 if(ps>0)A.with(()=>{A.circle(cx,cy,135,{fill:'#0b1830',stroke:'#fff',lw:8});A.text('M',cx,cy+8,{size:190,color:'#fff',weight:900,align:'center'});},{x:cx,y:cy,scale:ps});
}
if(t>=kP){A.rings(cx,cy,kP,{count:3,speed:500,gap:0.18,maxR:520,color:A.accent,lw:6,alpha:0.7});
 A.label('PARÍS',cx,1070,{size:68,bg:A.accent,color:'#fff',scale:A.pop(kP,0.45)});}
// secondary zone: badges
const bd=[[k1,'1','#FF3D3D','#fff'],[k2,'2','#FFC93C','#111'],[k5,'5','#2ECC71','#fff']];
const tp=A.p(kT,0.5,'softLand');
bd.forEach((b,i)=>{const sc=A.pop(b[0],0.45);if(sc<=0)return;const x=360+i*180,y=A.lerp(1460,1420,tp);
 const pulse=1+0.12*Math.max(0,1-Math.abs(t-b[0]-0.3)*3);
 A.with(()=>{A.circle(x,y,62,{fill:b[2],glow:b[2]});A.text(b[1],x,y+4,{size:72,color:b[3],weight:900,align:'center'});},{x,y,scale:sc*pulse,alpha:1-0.4*tp});});
if(tp>0){A.label('TECNOLOGÍA FRANCESA',540,1600,{size:50,bg:'#1f4fd1',color:'#fff',scale:A.pop(kT,0.45)});
 const fa2=A.p(kF,0.4);if(fa2>0){[['#1f4fd1',0],['#ffffff',1],['#FF3D3D',2]].forEach(([c,i])=>A.rect(450+i*60,1670,60,14,{fill:c,alpha:fa2}));}}

const W=A.W, ac=A.accent, mg='#FF4F8B';
A.bg('#071624','#0B2236',true);
const kc=A.k('carro',0.667), kn=A.k('neumáticos',1.333), kr=A.k('ruedan',2.0), kp=A.k('pistas',3.0), kno=A.k('no',3.667), kri=A.k('rieles',4.333);
// distancia recorrida
const u=Math.max(0,t-kr);
const dist = u<0.6 ? 520*u*u/1.2 : 520*(0.3+(u-0.6));
const moving = A.clamp(u/0.6);
// ---------- VÍA ----------
const trackY=950;
const pTrack=A.p(-0.2,0.6,'softLand');
const glow=A.p(kp,0.5,'snapSettle');
A.rect(60,trackY+34,960,50,{fill:'#0E2C44',alpha:pTrack});
A.line([[60,trackY+18],[1020,trackY+18]],{stroke:glow>0?ac:'#9FB7C9',lw:A.lerp(10,22,glow),progress:pTrack,alpha:0.9});
if(glow>0){
  A.lib.hatch(ctx,[[60,trackY+8],[1020,trackY+8],[1020,trackY+30],[60,trackY+30]],{angle:-0.8,spacing:10,width:2,color:ac});
  A.rect(60,trackY+6,960,24,{fill:ac,alpha:0.18*glow,glow:30*glow});
}
for(let i=0;i<14;i++){
  let x=((i*90-dist)%1260+1260)%1260-90;
  A.rect(x,trackY+48,40,8,{fill:'#2E5A78',alpha:pTrack});
}
// ---------- CARRO ----------
const pc=A.p(-0.3,0.8,'whip');
const carX=A.lerp(-1000,0,pc);
const settle=A.p(kc,0.4,'popOver');
const bob = moving*Math.sin(t*22)*3 + Math.sin(settle*Math.PI)*14;
A.with(()=>{
  const bx=150,by=490,bw=780,bh=300;
  A.rect(bx,by,bw,bh,{r:34,fill:'#10314A',stroke:ac,lw:6});
  A.lib.hatch(ctx,[[bx,by+200],[bx+bw,by+200],[bx+bw,by+bh],[bx,by+bh]],{angle:0.7,spacing:14,width:2,color:'#2A5877'});
  for(let i=0;i<4;i++) A.rect(bx+40+i*185,by+50,150,110,{r:14,fill:'#0A1C2B',stroke:'#CFE8F2',lw:3});
  A.rect(bx+20,by+bh-40,bw-40,10,{fill:ac,alpha:0.8});
  A.rect(bx+60,by+bh,bw-120,40,{r:10,fill:'#0B2234',stroke:'#7FA3B8',lw:3});
},{x:carX,y:bob});
// ---------- NEUMÁTICOS ----------
const wr=82, wy=trackY+18-wr;
const rot=dist/wr;
[[330,kn],[750,kn+0.15]].forEach(([wx,st])=>{
  const s=A.pop(st,0.45);
  if(s<=0) return;
  A.with(()=>{
    A.circle(wx,wy,wr,{fill:'#141A20',stroke:'#E8F4F8',lw:5});
    for(let i=0;i<16;i++){
      const a=rot+i*Math.PI/8;
      ctx.save();ctx.strokeStyle='#5C6B76';ctx.lineWidth=6;
      ctx.beginPath();ctx.moveTo(wx+Math.cos(a)*(wr-4),wy+Math.sin(a)*(wr-4));ctx.lineTo(wx+Math.cos(a)*(wr-20),wy+Math.sin(a)*(wr-20));ctx.stroke();ctx.restore();
    }
    A.circle(wx,wy,44,{fill:'#2B3A46',stroke:ac,lw:4});
    for(let i=0;i<5;i++){const a=rot+i*Math.PI*2/5;A.circle(wx+Math.cos(a)*26,wy+Math.sin(a)*26,6,{fill:'#CFE8F2'});}
    A.circle(wx,wy,10,{fill:ac});
  },{x:wx,y:wy,scale:s});
});
// etiqueta neumático
const pl=A.p(kn+0.25,0.4,'softLand');
if(pl>0 && t<kp+0.1){
  const fo=1-A.p(kp-0.1,0.2,'softInOut');
  A.arrow(500,1028,400,968,{progress:pl,color:'#FFFFFF',lw:5,alpha:fo});
  A.label('NEUMÁTICO',560,1062,{size:44,bg:ac,color:'#071624',scale:pl,alpha:pl*fo});
}
// líneas de velocidad
if(moving>0){
  A.particles(7,11,(i,r)=>{
    const y=530+r()*240, len=80+r()*120;
    const x=((900-((dist*1.6+r()*1200)%1300))+1300)%1300-100;
    A.line([[x,y],[x+len,y]],{stroke:'#CFE8F2',lw:4,alpha:0.5*moving});
  });
}
if(glow>0){
  A.label('PISTA PLANA',540,1062,{size:48,bg:ac,color:'#071624',scale:A.pop(kp,0.45)});
}
// ---------- COMPARACIÓN ----------
const pi=A.p(kp+0.25,0.5,'softLand');
if(pi>0){
  A.with(()=>{
    const lx=290, cy=1563, r=95, rr=rot*0.9;
    // losa plana
    A.rect(lx-190,1660,380,46,{r:6,fill:ac,alpha:0.95,glow:18});
    A.lib.hatch(ctx,[[lx-190,1676],[lx+190,1676],[lx+190,1706],[lx-190,1706]],{angle:-0.8,spacing:12,width:2,color:'#0B5866'});
    // neumático redondo con banda de rodadura
    A.circle(lx,cy,r,{fill:'#141A20',stroke:'#E8F4F8',lw:5});
    for(let i=0;i<18;i++){
      const a=rr+i*Math.PI*2/18;
      ctx.save();ctx.strokeStyle='#6F808C';ctx.lineWidth=9;ctx.lineCap='round';
      ctx.beginPath();ctx.moveTo(lx+Math.cos(a)*(r-6),cy+Math.sin(a)*(r-6));ctx.lineTo(lx+Math.cos(a)*(r-24),cy+Math.sin(a)*(r-24));ctx.stroke();ctx.restore();
    }
    A.circle(lx,cy,52,{fill:'#2B3A46',stroke:ac,lw:4});
    for(let i=0;i<5;i++){const a=rr+i*Math.PI*2/5;A.circle(lx+Math.cos(a)*31,cy+Math.sin(a)*31,7,{fill:'#CFE8F2'});}
    A.circle(lx,cy,12,{fill:ac});
    // contacto ancho
    A.rect(lx-46,1652,92,10,{r:4,fill:'#FFFFFF',alpha:0.8});
    A.text('PISTA',lx,1420,{size:56,color:'#B8F6FF',weight:900,align:'center',stroke:'#071624',strokeWidth:6});
    const ck=A.p(kp+0.6,0.35,'snapSettle');
    A.line([[lx+110,1440],[lx+140,1475],[lx+195,1395]],{stroke:'#7CFFB2',lw:12,progress:ck});
  },{alpha:pi,y:(1-pi)*40});
}
const pr=A.p(kno,0.45,'snapSettle');
if(pr>0){
  const xp=A.p(kri,0.35,'crashIn');
  const rx=790, cy=1553, r=88;
  A.with(()=>{
    // pestaña (disco mayor detrás)
    A.circle(rx,cy,r+20,{fill:'#55636E',stroke:'#E8F4F8',lw:4});
    // riel visto de lado: cabeza, alma, patín
    A.rect(rx-170,1641,340,26,{r:4,fill:'#C9D6DF',stroke:'#E8F4F8',lw:3});
    A.rect(rx-170,1667,340,26,{fill:'#5E7486'});
    A.rect(rx-170,1693,340,22,{r:4,fill:'#9FB7C9',stroke:'#E8F4F8',lw:3});
    // la pestaña baja por el costado de la cabeza
    ctx.save();ctx.beginPath();ctx.arc(rx,cy,r+20,0.25*Math.PI,0.75*Math.PI);ctx.strokeStyle='#E8F4F8';ctx.lineWidth=4;ctx.stroke();ctx.restore();
    // rueda de acero
    A.circle(rx,cy,r,{fill:'#7A8A96',stroke:'#FFFFFF',lw:5});
    A.circle(rx,cy,r-14,{fill:'#5C6B76'});
    for(let i=0;i<6;i++){
      const a=rot*0.9+i*Math.PI/3;
      ctx.save();ctx.strokeStyle='#A9B8C3';ctx.lineWidth=8;
      ctx.beginPath();ctx.moveTo(rx+Math.cos(a)*22,cy+Math.sin(a)*22);ctx.lineTo(rx+Math.cos(a)*(r-18),cy+Math.sin(a)*(r-18));ctx.stroke();ctx.restore();
    }
    A.circle(rx,cy,22,{fill:'#CFE8F2'});
    A.text('PESTAÑA',rx,1745-20,{size:1,alpha:0});
